BEGIN;
CREATE TABLE IF NOT EXISTS branch_business_hour(id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,branch_id integer NOT NULL REFERENCES branch(id) ON DELETE CASCADE,day_of_week varchar(12) NOT NULL,open_time time NULL,close_time time NULL,is_closed boolean NOT NULL DEFAULT false,display_order integer NOT NULL,created_at timestamptz NOT NULL DEFAULT NOW(),updated_at timestamptz NOT NULL DEFAULT NOW(),UNIQUE(branch_id,day_of_week));
ALTER TABLE branch_ai_setting ADD COLUMN IF NOT EXISTS assistant_name varchar(200) NOT NULL DEFAULT '';
ALTER TABLE branch_ai_setting ADD COLUMN IF NOT EXISTS prompt_objective varchar(4000) NULL;
ALTER TABLE branch_ai_setting ADD COLUMN IF NOT EXISTS prompt_personality varchar(2000) NULL;
ALTER TABLE branch_ai_setting ADD COLUMN IF NOT EXISTS prompt_required_rules varchar(8000) NULL;
ALTER TABLE branch_ai_setting ADD COLUMN IF NOT EXISTS prompt_fixed_branch_info varchar(8000) NULL;
ALTER TABLE branch_ai_setting ADD COLUMN IF NOT EXISTS prompt_additional_instructions varchar(8000) NULL;
ALTER TABLE branch_ai_setting ADD COLUMN IF NOT EXISTS transfer_message varchar(1000) NOT NULL DEFAULT 'Un asesor continuará con tu atención.';
COMMIT;
